-- Apply supabase-student-first-login.sql before running this import.
-- Imports the 85 accepted 2026-2027 dental prosthetics students. Existing student accounts are left unchanged.
-- Personal admissions details are stored separately in the service-role-only student_admission_records table.
begin;

lock table public.students in access exclusive mode;
lock table public.student_admission_records in access exclusive mode;

create sequence if not exists public.students_num_seq;
select setval('public.students_num_seq', coalesce((select max(num) from public.students), 0) + 1, false);
alter table public.students alter column num set default nextval('public.students_num_seq');
alter sequence public.students_num_seq owned by public.students.num;

create temp table student_import_stage on commit drop as
select
  U&"\0627\0644\0631\0642\0645\0020\0627\0644\062C\0627\0645\0639\064A",
  U&"\0643\0644\0645\0629\0020\0627\0644\0633\0631",
