  U&"\0627\0644\0643\0646\064A\0629",
  U&"\0627\0644\0642\0633\0645",
  U&"\0631\0642\0645\0020\0627\0644\0647\0627\062A\0641",
  U&"\0627\0644\0628\0631\064A\062F\0020\0627\0644\0625\0644\0643\062A\0631\0648\0646\064A",
  U&"\0646\0648\0639\0020\0627\0644\062A\0633\062C\064A\0644",
  U&"\0627\0644\0633\0646\0647\0020\0627\0644\062F\0631\0627\0633\064A\0629",
  force_password_change
from public.students
with no data;

